package net.atlasauth.pca.mpc.net

import java.math.BigInteger
import net.atlasauth.pca.mpc.NetForensics.SlotDisclosure
import net.atlasauth.pca.mpc.NetPa.AW
import net.atlasauth.pca.mpc.NetPa.PA

/**
 * The offline material one party holds when the online phase starts, dealt by a trusted dealer or generated by the parties from OT.
 * [mode] is "trusted-dealer" or "no-dealer" (a trusted dealer knows every share and key); [tagged] says whether the shares carry
 * pairwise tags (identifiable abort; only the trusted-dealer mode provides them); [triples] holds a, b, c, then (a-hat, c-hat) per
 * sacrifice partner; [inputs] holds authenticated masks (dealer) or input bits (no-dealer), indexed owner * C + chain.
 */
class Prep(
    val mode: String,
    val tagged: Boolean,
    val delta: BigInteger,
    val alpha: Array<PA>,
    val triples: Array<Array<AW>>,
    val inputs: Array<AW>,
    val myPlain: Array<BigInteger>,
    val checkMask: AW?,
    val forensics: Forensics?,
) {
    /** The OT transcript of the triple products, kept to attribute a failed sacrifice (no-dealer mode only). */
    class Forensics(val gadget: Array<BigInteger>, val rows: Int, val slots: Int, val disclose: (Int) -> List<SlotDisclosure>)
}
